INSERT INTO `evaluations` VALUES (1,1,NULL,NULL,'YN001','10-420527KF00001','BK001',5,5,5,5,'干净整洁,维护良好','烤房设备很好，温湿度控制精准，李师傅服务态度也很好！','技术精湛，操作熟练，非常满意！',NULL,'2025-06-15 15:00:00','2026-06-29 16:53:17','2026-06-30 11:18:55'),(2,2,NULL,NULL,'YN001','10-420527KF00003','BK002',4,4,4,4,'温度稳定','整体不错，温湿度控制稍微有点波动','服务周到，响应及时',NULL,'2025-06-10 10:00:00','2026-06-29 16:53:17','2026-06-30 11:18:55'),(3,3,NULL,NULL,'YN001','10-420527KF00002','BK002',5,5,5,5,'操作方便,温度稳定','设备完好度高，烘烤过程稳定','操作规范，服务热情',NULL,'2025-06-22 17:00:00','2026-06-29 16:53:17','2026-06-30 11:18:55'),(4,5,'','','YN001','10-420527KF00001','BK001',5,4,5,5,'通风良好，温度稳定，操作方便','','不够细心，态度欠佳',NULL,'2026-06-30 09:17:53','2026-06-30 09:17:53','2026-06-30 09:17:53'),(5,NULL,'','ASG2025001','YN001','10-420527KF00005','BK003',3,1,1,1,'保温性差','测试内容输入','响应较慢，态度欠佳',NULL,'2026-06-30 11:35:54','2026-06-30 11:35:54','2026-06-30 11:35:54'),(6,6,'','','YN001','10-420527KF00006','BK002',1,1,1,2,'需要维修','烤房没人管，服务一点也不好','响应较慢，不够细心，态度欠佳',NULL,'2026-07-01 11:26:32','2026-07-01 11:26:32','2026-07-01 11:26:32'),(9,10,NULL,'ASGYN002202401','YN002','10-420527KF00002','BK002',4,4,4,5,'设备完好,响应及时,温控稳定','设备状态不错，后半程湿度略有波动，但整体质量达标。','服务响应快，建议下次提前检查风机转速。',NULL,'2024-08-26 11:20:00','2026-07-15 21:03:30','2026-07-15 21:03:30'),(10,11,NULL,NULL,'YN002','10-420527KF00003','BK001',5,5,5,5,'成色好,技术到位,过程稳定','烘烤过程稳定，温湿度控制准确，成色比上一季更好。','沟通及时，装炕和排湿节点把握得很好。',NULL,'2023-08-23 10:00:00','2026-07-15 21:03:30','2026-07-15 21:03:30');
