--
-- Table structure for table `oven_assignments`
--

DROP TABLE IF EXISTS `oven_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oven_assignments` (
  `id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分配单号',
  `user_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '烟农用户ID',
  `oven_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '烤房编号',
  `baker_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '烘烤师ID',
  `season_year` smallint unsigned NOT NULL COMMENT '分配年度/烘烤季',
  `season_name` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '烘烤季名称',
  `status` enum('assigned','active','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `assigned_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '后台分配人',
  `assigned_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '分配时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_oven_season` (`user_id`,`oven_id`,`season_year`),
  KEY `idx_user` (`user_id`),
  KEY `idx_oven` (`oven_id`),
  KEY `idx_baker` (`baker_id`),
  KEY `idx_season` (`season_year`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='烤房分配表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `oven_assignments`
--

